/// <summary>
/// MPJ_5012_RebateProcess
/// Service class to run the update of Rebate Item groups by adding new items
/// </summary>
class METRebateInclusionsUpdateService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// MPJ_5012_RebateProcess
    /// Method to insert New created items to Rebate group based on Item category.
    /// </summary>
    /// <param name = "_contract"> METRebateInclusionsUpdateContract </param>
    public void processOperation(METRebateInclusionsUpdateContract _contract)
    {
        List                    itemNum;
        TAMRebateGroupLink      rebateGroupLink, rebateGroupLinkNew;
        InventTable             inventTableNew;
        RecordInsertList        rebateGroupLinkRecordList;

        CreatedDateTime         itemCreatedDateTime;
        Query                   query;
        QueryRun                queryRun;
        QueryBuildDataSource    qbdsInventTable, qbdsMETInventTable, qbdsExistingCategory, qbdsNewCategory, 
                                qbdsExistingInventTable, qbdsRebateGroupLink, qbdsRebateGroup;

        itemCreatedDateTime = DateTimeUtil::newDateTime(DateTimeUtil::date(DateTimeUtil::getSystemDateTime()), DateTimeUtil::time(DateTimeUtil::minValue()));
        itemNum = _contract.parmItemId();
        rebateGroupLinkRecordList = new  RecordInsertList(tableNum(TAMRebateGroupLink));

        query = new Query();
        qbdsInventTable = query.addDataSource(tablenum(InventTable), "@MET:NewItems");
        if(itemNum)
        {
            qbdsInventTable.addRange(fieldnum(InventTable, ItemId)).value(strList2str(itemNum));
        }
        else
        {
            qbdsInventTable.addRange(fieldnum(InventTable, CreatedDateTime)).value(queryRange(itemCreatedDateTime, DateTimeUtil::getSystemDateTime()));
        }
        
        qbdsInventTable.addGroupByAndSelectionField(fieldNum(InventTable, RecID));
        qbdsInventTable.addGroupByAndSelectionField(fieldNum(InventTable, TableId));
        qbdsInventTable.addGroupByAndSelectionField(fieldNum(InventTable, ItemId));
        qbdsInventTable.addGroupByAndSelectionField(fieldNum(InventTable, Product));

        qbdsMETInventTable = qbdsInventTable.addDataSource(tableNum(METInventTable));
        qbdsMETInventTable.fetchMode(QueryFetchMode::One2One);
        qbdsMETInventTable.relations(true);
        qbdsMETInventTable.joinMode(JoinMode::InnerJoin);
        qbdsMETInventTable.addRange(fieldNum(METInventTable,RebateInclusion)).value(queryValue(NoYes::Yes));

        qbdsExistingCategory = qbdsInventTable.addDataSource(tableNum(EcoResProductCategory), "@MET:ExistingCategory");
        qbdsExistingCategory.fetchMode(QueryFetchMode::One2One);
        qbdsExistingCategory.relations(true);

        qbdsNewCategory = qbdsExistingCategory.addDataSource(tableNum(EcoResProductCategory), "@MET:NewCategory");
        qbdsNewCategory.addRange(fieldNum(EcoResProductCategory, Category)).value(strFmt("@MET:CategoryMatching"));
        qbdsNewCategory.addGroupByAndSelectionField(fieldNum(EcoResProductCategory, Category));
        
        qbdsExistingInventTable = qbdsNewCategory.addDataSource(tableNum(InventTable), "@MET:ExistingItems");
        qbdsExistingInventTable.relations(true);
        
        qbdsRebateGroupLink = qbdsExistingInventTable.addDataSource(tableNum(TAMRebateGroupLink));
        qbdsRebateGroupLink.relations(true);
        qbdsRebateGroupLink.addGroupByAndSelectionField(fieldNum(TAMRebateGroupLink, RebateGroupId));
                
        qbdsRebateGroup = qbdsRebateGroupLink.addDataSource(tableNum(TAMRebateGroup));
        qbdsRebateGroup.relations(false);
        qbdsRebateGroup.linkFields(fieldStr(TAMRebateGroup,RebateGroupId),fieldStr(TAMRebateGroupLink ,RebateGroupId));
        
        qbdsRebateGroup.addRange(fieldNum(TAMRebateGroup, ModuleInventCustVend)).value(queryValue(ModuleInventCustVend::Invent));
        qbdsRebateGroup.addRange(fieldNum(TAMRebateGroup, METCategoryGroup)).value(queryValue(NoYes::Yes));
        qbdsRebateGroup.addGroupByAndSelectionField(fieldNum(TAMRebateGroup, RebateGroupId));
        
        queryRun = new QueryRun(query);
        while(queryRun.next())
        {
            rebateGroupLink = queryRun.get(tableNum(TAMRebateGroupLink));
            inventTableNew = queryRun.get(tableNum(InventTable));

            rebateGroupLinkNew.RebateGroupId =rebateGroupLink.rebateGroupId;
            rebateGroupLinkNew.RefRecId = inventTableNew.RecId;
            rebateGroupLinkNew.RefTableId = inventTableNew.TableId;
            rebateGroupLinkNew.ModuleInventCustVend = ModuleInventCustVend::Invent;
            rebateGroupLinkRecordList.add(rebateGroupLinkNew);
        }
        rebateGroupLinkRecordList.insertDatabase();
    }
